import{_ as r,o as n,c as i,ah as t}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Recherche: Das „Tickerverbot“ im Wöginger-Prozess","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/2026-03-26-tickerverbot-woeginger.md","filePath":"recherche/2026-03-26-tickerverbot-woeginger.md"}'),s={name:"recherche/2026-03-26-tickerverbot-woeginger.md"};function a(o,e,g,d,u,h){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="recherche-das-„tickerverbot-im-woginger-prozess" tabindex="-1">Recherche: Das „Tickerverbot“ im Wöginger-Prozess <a class="header-anchor" href="#recherche-das-„tickerverbot-im-woginger-prozess" aria-label="Permalink to &quot;Recherche: Das „Tickerverbot“ im Wöginger-Prozess&quot;">​</a></h1><p><strong>Datum:</strong> 26. März 2026 <strong>Quelle:</strong> Ö1 Mittagsjournal / Medienberichte</p><h3 id="zusammenfassung-der-vorfalle" tabindex="-1">Zusammenfassung der Vorfälle <a class="header-anchor" href="#zusammenfassung-der-vorfalle" aria-label="Permalink to &quot;Zusammenfassung der Vorfälle&quot;">​</a></h3><p>Am 24. März 2026 erließ das Landesgericht Linz in der Verhandlung gegen ÖVP-Klubobmann August Wöginger ein überraschendes Verbot für Live-Ticker aus dem Gerichtssaal.</p><p><strong>Die Begründung des Gerichts:</strong> Die zuständige Richterin argumentierte, dass die unmittelbare Veröffentlichung von Zeugenaussagen in Echtzeit die Gefahr berge, dass nachfolgende Zeugen ihre Aussagen anpassen könnten. Um die Wahrheitsfindung nicht zu gefährden, wurde die Live-Berichterstattung untersagt.</p><p><strong>Die Kritik:</strong> Die Entscheidung löste eine heftige Debatte über die Pressefreiheit und das Prinzip der Öffentlichkeit von Gerichtsverfahren aus.</p><ul><li><strong>Rechtsexperten:</strong> Kritisierten, dass Zeugen sich ohnehin über Radio, Fernsehen oder Abendzeitungen informieren können. Ein Tickerverbot sei im digitalen Zeitalter ein „anachronistischer Eingriff“.</li><li><strong>Journalisten-Organisationen:</strong> Sahen darin eine gefährliche Einschränkung der Berichterstattung über einen Prozess von hohem öffentlichen Interesse.</li></ul><p><strong>Inhaltlicher Kontext des Prozesses:</strong> Parallel zur Debatte um das Tickerverbot wurden im Mittagsjournal die Kernvorwürfe rekapituliert:</p><ul><li>Intervention Wögingers bei Thomas Schmid (damals Finanzministerium) im Jahr 2017.</li><li>Ziel: Besetzung eines ÖVP-Bürgermeisters als Leiter des Finanzamts Braunau, trotz schlechterer Qualifikation (62 vs. 98 Punkte).</li><li>Neue Zeugenaussagen bestätigten den Druck auf den bestgereihten Kandidaten, auf den Posten zu verzichten.</li></ul><h3 id="einordnung-fur-den-dokfilm" tabindex="-1">Einordnung für den Dokfilm <a class="header-anchor" href="#einordnung-fur-den-dokfilm" aria-label="Permalink to &quot;Einordnung für den Dokfilm&quot;">​</a></h3><p>Das Tickerverbot ist ein weiteres Puzzlestück in der Erzählung über das <strong>„System der Intransparenz“</strong>. Während wir im Film den „Pointillismus des Geldes“ (die sichtbaren Spuren) verfolgen, zeigt das Tickerverbot den Versuch, die Sichtbarkeit des juristischen Prozesses in Echtzeit zu unterbinden.</p><p><strong>Status-Update (27.03.2026):</strong> Das Verbot wurde am Vormittag des 27. März 2026 durch Richterin Melanie Halbig wieder aufgehoben.</p><ul><li><strong>Begründung:</strong> Die heute geladenen Zeugen verfügen laut Gericht überwiegend über „mittelbare Wahrnehmungen“ (z. B. Finanzamt-interner Flurfunk), wodurch eine gegenseitige Beeinflussung durch Ticker-Inhalte nicht mehr gegeben sei.</li><li><strong>Fazit für die Recherche:</strong> Das Ticker-Intermezzo hat gezeigt, wie fragil die Transparenz in Prozessen gegen Spitzenpolitiker sein kann. Der mediale und rechtliche Widerstand gegen das Verbot war ausschlaggebend für die rasche Korrektur. Das Urteil gegen August Wöginger wird nun für den <strong>4. Mai 2026</strong> erwartet.</li></ul><p><em>Dokumentiert für das Projekt „HortenMysterium“.</em></p>',14)])])}const m=r(s,[["render",a]]);export{c as __pageData,m as default};
